/* LAPENG original frontend. No dependency on remote images, fonts or UI services. */
const $=s=>document.querySelector(s), e=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const state={token:sessionStorage.getItem('lapeng_token')||'',user:null,mode:localStorage.getItem('lapeng_mode')||'buyer',q:'',activeCategory:'',backendSearch:false,providers:[],catalogue:[],requests:[],detail:null,loading:false,geo:null,geoStatus:'',cartCount:0};
// Location is opt-in and kept only in JavaScript memory for this tab.
async function inAppLocationConsent(){
  return new Promise(resolve=>{
    const existing=document.getElementById('lapeng-location-consent'); if(existing)existing.remove();
    const layer=document.createElement('div');layer.id='lapeng-location-consent';layer.className='lapeng-consent-layer';
    layer.innerHTML=`<section class="lapeng-consent-card" role="dialog" aria-modal="true" aria-labelledby="lapeng-location-title"><span class="eyebrow">YOUR LOCATION, YOUR CHOICE</span><h2 id="lapeng-location-title">Find what's near you</h2><p>Allow LAPENG to use your device's approximate location to show nearby hairstylists, shops, carpenters and other local services. We only use it for this session and do not save GPS coordinates to your account.</p><p class="hint">Your browser may ask for device permission after you choose Allow. You can still explore without sharing your location.</p><div class="form-actions"><button class="btn" type="button" id="lapeng-consent-yes">Allow location</button><button class="btn ghost" type="button" id="lapeng-consent-no">Not now</button></div></section>`;
    document.body.appendChild(layer);
    function done(ok){layer.remove();resolve(ok)}
    layer.querySelector('#lapeng-consent-yes').onclick=()=>done(true);
    layer.querySelector('#lapeng-consent-no').onclick=()=>done(false);
  });
}
async function askLocation(){
  if(!await inAppLocationConsent())throw Error('Location sharing declined. You can still browse without location.');
  if(!navigator.geolocation)throw Error('This browser cannot share location. Use a browser with location access.');
  if(!window.isSecureContext)throw Error('Location needs HTTPS or localhost.');
  return await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(
    p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),
    err=>reject(Error(err.code===1?'Location permission denied. You can still browse normally.':'Unable to determine location. Check device location services.')),
    {enableHighAccuracy:false,timeout:12000,maximumAge:120000}));
}
function geoText(){return state.geo?`Location enabled for this tab · accuracy about ${Math.round(state.geo.accuracy)} m`:'Location is off · browse anywhere or enable nearby discovery';}
async function maybeOfferLocation(){
  if(state.geo||sessionStorage.getItem('lapeng_location_offered')==='1')return;
  sessionStorage.setItem('lapeng_location_offered','1');
  try{state.geo=await askLocation();await nearbyRefresh();await render();toast('Showing nearby services. You can turn off location at any time.');}
  catch(err){/* Declining leaves all browsing available, without nags. */}
}
async function nearbyRefresh(){
  const params=new URLSearchParams({latitude:String(state.geo.latitude),longitude:String(state.geo.longitude),nearby:'true'});
  if(state.q)params.set('q',state.q);
  state.providers=await api('/providers?'+params.toString());
}
const icon='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M10 29 32 11l22 18v25H10z" fill="none" stroke="currentColor" stroke-width="5" stroke-linejoin="round"/><path d="M25 54V36h14v18" fill="none" stroke="currentColor" stroke-width="4"/></svg>';
const go=(path)=>{location.hash='#'+path};
// Keep in-app navigation predictable, including for pages opened from a bookmarked URL.
const routeTrail=[decodeURIComponent(location.hash.slice(1)||'/')];
let returningViaAppBack=false;
function recordRoute(){
  const current=path();
  if(returningViaAppBack){returningViaAppBack=false;return;}
  if(routeTrail[routeTrail.length-1]!==current){routeTrail.push(current);if(routeTrail.length>80)routeTrail.shift();}
}
function safeBackDestination(){
  const key=path().split('?')[0];
  if(key==='/explore'||key==='/signin'||key==='/signup'||key==='/about'||key==='/trust'||key==='/terms'||key==='/privacy')return '/';
  if(key==='/dashboard')return '/explore';if(key==='/checkout')return '/cart';if(['/cart','/orders','/bookings','/settlements'].includes(key))return '/dashboard';if(key.startsWith('/order/'))return '/orders';
  if(key.startsWith('/product/'))return '/explore';if(key.startsWith('/provider/')&&!key.endsWith('/new'))return '/explore';
  if(key.startsWith('/guardian/'))return '/trust';if(key.startsWith('/requests/')&&key!='/requests/new')return '/requests';
  if(key==='/provider/new'||key==='/requests/new'||key==='/messages'||key==='/settings'||key==='/requests')return state.user?'/dashboard':'/explore';
  return '/explore';
}
function navigateBack(){
  // Only step through internal LAPENG routes. Never send someone out to another website.
  if(routeTrail.length>1){
    const current=routeTrail.pop();
    let previous=routeTrail[routeTrail.length-1];
    while(previous===current&&routeTrail.length>1){routeTrail.pop();previous=routeTrail[routeTrail.length-1];}
    returningViaAppBack=true;
    go(previous);
    if(path()===previous){returningViaAppBack=false;render();}
    return;
  }
  const fallback=safeBackDestination();
  if(path()!==fallback)go(fallback);else go('/');
}
function backBar(){
  const key=path().split('?')[0];
  if(key==='/')return '';
  return `<div class="app-back-wrap"><button class="app-back" type="button" data-action="navigate-back" aria-label="Go back to previous page"><span aria-hidden="true">←</span><span>Back</span></button></div>`;
}

// Branded LAPENG modal: keeps customer decisions and messages inside the app.
// Browser / OS permission prompts and PayPal approval screens remain external by design.
function lapengDialog({title='Please confirm',message='',kind='confirm',initial='',label='Your response',required=false,minLength=0,destructive=false}={}){
  return new Promise(resolve=>{
    const previous=document.activeElement;
    const layer=document.createElement('div');
    layer.className='lapeng-dialog-overlay';
    const id='lapeng-dialog-'+Date.now();
    layer.innerHTML=`<section class="lapeng-dialog" role="dialog" aria-modal="true" aria-labelledby="${id}-title" aria-describedby="${id}-message">
      <div class="lapeng-dialog-head"><span class="eyebrow">LAPENG · ${kind==='confirm'?'CONFIRM ACTION':'YOUR RESPONSE'}</span><button type="button" class="lapeng-dialog-close" aria-label="Close dialog" data-dialog-cancel>×</button></div>
      <h2 id="${id}-title"></h2><p id="${id}-message" class="lapeng-dialog-message"></p>
      ${kind==='input'?`<form class="lapeng-dialog-form"><label for="${id}-field"></label><textarea id="${id}-field" rows="4" maxlength="2000"></textarea><p class="lapeng-dialog-error" role="alert" hidden></p><div class="lapeng-dialog-actions"><button class="btn ghost" type="button" data-dialog-cancel>Cancel</button><button class="btn" type="submit">Continue</button></div></form>`:
      `<div class="lapeng-dialog-actions"><button class="btn ghost" type="button" data-dialog-cancel>Cancel</button><button class="btn ${destructive?'danger':''}" type="button" data-dialog-accept>${destructive?'Delete / confirm':'Confirm'}</button></div>`}
    </section>`;
    const titleEl=layer.querySelector('h2'),messageEl=layer.querySelector('.lapeng-dialog-message');
    titleEl.textContent=title;messageEl.textContent=message;
    const input=layer.querySelector('textarea');
    if(input){input.value=initial;layer.querySelector('label').textContent=label;}
    const oldOverflow=document.body.style.overflow;
    document.body.appendChild(layer);document.body.style.overflow='hidden';
    let finished=false;
    const close=value=>{if(finished)return;finished=true;document.removeEventListener('keydown',onKey,true);layer.remove();document.body.style.overflow=oldOverflow;if(previous?.isConnected)previous.focus();resolve(value);};
    function onKey(ev){
      if(ev.key==='Escape'){ev.preventDefault();ev.stopPropagation();close(kind==='confirm'?false:null);return;}
      if(ev.key==='Tab'){
        const focusable=[...layer.querySelectorAll('button:not([disabled]),textarea:not([disabled])')];
        if(!focusable.length)return;
        const first=focusable[0],last=focusable[focusable.length-1];
        if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}
        else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}
      }
    }
    document.addEventListener('keydown',onKey,true);
    layer.querySelectorAll('[data-dialog-cancel]').forEach(b=>b.addEventListener('click',()=>close(kind==='confirm'?false:null)));
    layer.querySelector('[data-dialog-accept]')?.addEventListener('click',()=>close(true));
    layer.addEventListener('pointerdown',ev=>{if(ev.target===layer)close(kind==='confirm'?false:null);});
    layer.querySelector('form')?.addEventListener('submit',ev=>{
      ev.preventDefault();const value=input.value.trim();
      if((required&&!value)||value.length<minLength){const error=layer.querySelector('.lapeng-dialog-error');error.hidden=false;error.textContent=value?`Please enter at least ${minLength} characters.`:'Please enter a response.';input.focus();return;}
      close(value);
    });
    (input||layer.querySelector('[data-dialog-cancel]'))?.focus();
  });
}
async function lapengConfirm(message,options={}){
  return lapengDialog({kind:'confirm',title:options.title||'Confirm this action',message,destructive:!!options.destructive});
}
async function lapengPrompt(message,initial='',options={}){
  return lapengDialog({kind:'input',title:options.title||'A quick question',message,initial,label:options.label||'Your message',required:!!options.required,minLength:options.minLength||0});
}

function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>t.style.display='none',4800)}
async function api(url,opts={}){const h={'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(opts.headers||{})};let res=await fetch('/api'+url,{...opts,headers:h});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.detail||'Request failed');return data}
async function refresh(){try{const [p,r,c]=await Promise.all([api('/providers'),api('/requests'),api('/commerce/catalogue')]);state.providers=p;state.requests=r;state.catalogue=c;if(state.token){state.user=await api('/me');await updateCartCount()}else state.cartCount=0}catch(err){if(/Session expired|Sign in required/.test(err.message)){state.token='';state.user=null;sessionStorage.removeItem('lapeng_token')}else console.error(err)}}
async function updateCartCount(){
  if(!state.token||!state.user){state.cartCount=0;return;}
  try{const result=await api('/commerce/cart');state.cartCount=result.lines.reduce((sum,line)=>sum+line.qty,0)}catch(err){console.warn('Cart count unavailable',err)}
  document.querySelectorAll('[data-cart-count]').forEach(el=>{el.textContent=state.cartCount>99?'99+':String(state.cartCount);el.hidden=!state.cartCount});
  const cart=document.querySelector('[data-cart-link]');if(cart)cart.setAttribute('aria-label',`Shopping cart, ${state.cartCount} item${state.cartCount===1?'':'s'}`);
}
function paypalTransition(){let overlay=document.getElementById('lapeng-paypal-transition');if(overlay)return;overlay=document.createElement('div');overlay.id='lapeng-paypal-transition';overlay.innerHTML='<div class="lapeng-paypal-transition-card" role="status" aria-live="polite"><div class="lapeng-payment-spinner" aria-hidden="true"></div><span class="eyebrow">LAPENG SECURE CHECKOUT</span><h2>Taking you to PayPal</h2><p>Review and approve your Sandbox payment securely with PayPal. Your order is not paid until LAPENG verifies the capture.</p><span class="lapeng-sandbox-indicator">PayPal Sandbox · Test payment</span></div>';document.body.appendChild(overlay)}
