const fileBase64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Could not read image'));r.readAsDataURL(file)});
function visibleProviders(){let q=state.q.trim().toLowerCase();const matches=state.providers.filter(p=>categoryMatch(p,state.activeCategory)&&(!q||state.backendSearch||(p.name+' '+p.category+' '+p.bio+' '+p.skills+' '+p.kind+' '+(p.public_id||'')).toLowerCase().includes(q)));const real=matches.filter(p=>p.owner_id!==null);const demo=matches.filter(p=>p.owner_id===null);const seen=new Set();const selected=[];for(const p of demo){const img=previewImage(p);if(!img||seen.has(img))continue;seen.add(img);selected.push(p);if(selected.length===6)break;}return [...real,...selected];}
function pcard(p){const demo=p.owner_id===null;const cover=(p.photos||[]).find(im=>im.role==='avatar')||(p.photos||[]).find(im=>im.role==='cover')||(p.photos||[])[0];const sample=demo?previewImage(p):null;const photo=cover?.url||(sample?'/static/media/'+sample:'');return `<article class="card provider ${demo?'demo-provider':'member-provider'}"><div class="provider-photo ${photo?'':'provider-photo-empty'}">${photo?`<img src="${e(photo)}" loading="lazy" alt="${e(p.name)} portfolio">`:`<div class="avatar">${e(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`}${demo?'<span class="preview-chip">Preview example</span>':''}</div><div class="provider-body"><div class="provider-kicker">${e(p.category)} · ${e(p.city)}</div><h3>${e(p.name)}</h3><p class="provider-description">${e(p.bio)}</p><div class="provider-extra"><span>${p.remote?'Remote available':'Local offering'}</span>${Number.isFinite(p.distance_km)?`<span>${e(p.distance_km)} km away</span>`:''}<span>${demo?'Example only':'Community provider'}</span></div><div class="provider-bottom"><span class="meta">${e(p.public_id||refId('P',p.id))} · ${demo?'Preview only':p.reviews?`${e(p.reviews)} verified reviews`:'New provider'}</span><button class="btn outline small" data-action="profile" data-id="${p.id}">View profile →</button></div></div></article>`}

function landing(){
  const categories=[['Fashion','fashion','beauty.webp'],['Home & living','home','carpentry.webp'],['Beauty','beauty','beauty.webp'],['Food & bakery','food','bakery.webp'],['Digital talent','digital','web.webp'],['Local services','home-services','carpentry.webp']];
  const catTiles=categories.map(([name,id,img])=>`<a class="lapeng-landing-category" href="#/explore" data-category-link="${id}"><img src="/static/media/${img}" alt="${e(name)} example" loading="lazy"><span>${e(name)} <span aria-hidden="true">↗</span></span></a>`).join('');
  const real=(state.catalogue||[]).filter(l=>l&&l.provider_id&&l.photo_url).slice(0,3);
  const featured=real.length?`<section class="lapeng-landing-featured"><div class="lapeng-landing-section-title"><div><span class="eyebrow">FROM THE COMMUNITY</span><h2>Recently added</h2></div><a href="#/explore">Explore all →</a></div><div class="lapeng-landing-featured-grid">${real.map(l=>`<a href="#/provider/${l.provider_id}" class="lapeng-featured-card"><img src="${e(l.photo_url)}" alt="${e(l.title)}" loading="lazy"><div><strong>${e(l.title)}</strong><span>${money(l.price,l.currency)}</span></div><small>${e(l.catalog_category||l.kind||'Product or service')}</small></a>`).join('')}</div></section>`:'';
  return `<main class="lapeng-public lapeng-landing-new"><section class="lapeng-landing-hero"><div class="lapeng-landing-copy"><span class="eyebrow">THE COMMUNITY MARKETPLACE</span><h1>Find what you need.<br><em>Discover what's possible.</em></h1><p>Products, local services and global talent — all in one place.</p><form data-form="search" class="lapeng-landing-search"><label for="landing-search" class="sr-only">Search LAPENG</label><input id="landing-search" name="q" placeholder="Search products, services or skills…" autocomplete="off" required><button type="submit" class="btn">Search</button></form><div class="hero-buttons"><a class="btn" href="#/signin">Get Started</a><a class="btn outline" href="#/explore">Explore</a></div></div><div class="lapeng-landing-pictures" aria-label="Examples of services and products available on LAPENG"><img src="/static/media/bakery.webp" alt="Cakes and bakery products"><img src="/static/media/carpentry.webp" alt="Craftsmanship and furniture"><img src="/static/media/beauty.webp" alt="Beauty products"><img src="/static/media/web.webp" alt="Web development services"></div></section><section class="lapeng-landing-categories"><div class="lapeng-landing-section-title"><div><span class="eyebrow">SHOP · BOOK · HIRE</span><h2>Explore what matters</h2></div><a href="#/explore">All categories →</a></div><div class="lapeng-landing-category-grid">${catTiles}</div></section>${featured}<section class="lapeng-landing-promises"><span>⌕ <b>Discover nearby services</b></span><span>♡ <b>Save what you love</b></span><span>▣ <b>Shop or book with confidence</b></span></section><p class="lapeng-landing-disclaimer">Category images are illustrative. Listings, prices and reviews come from real community records.</p></main>`;
}
function signin(signup=false){return `<div class="auth-shell"><div class="auth-art"><span class="eyebrow">A COMMUNITY THAT WORKS TOGETHER</span><h1>${signup?'Make room for what comes next.':'Good to have you back.'}</h1><p>Discover services, offer your skills and manage trusted collaborations. One account. Two workspaces.</p><div style="margin-top:32px;color:#e4c9d7">✦ Local opportunity &nbsp;&nbsp; ✦ Global reach &nbsp;&nbsp; ✦ Human-centred trust</div></div><div class="auth-form"><div class="panel"><span class="eyebrow">${signup?'GET STARTED':'SIGN IN'}</span><h1 class="page-title">${signup?'Join LAPENG':'Welcome back'}</h1><p class="subtle">${signup?'Your account can switch between buying and offering services.':'Continue your projects, discoveries and conversations.'}</p><form data-form="${signup?'signup':'signin'}">${signup?`<div class="field"><label>Your name</label><input name="name" minlength="2" required placeholder="Your name"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input name="password" type="password" ${signup?'minlength="12"':''} required placeholder="${signup?'At least 12 characters':'Your password'}"></div>${signup?'<p class="hint">By creating an account you accept our <a href="#/terms">terms</a> and acknowledge our <a href="#/privacy">privacy notice</a>.</p>':''}<button class="btn" style="width:100%">${signup?'Create account':'Sign in'} →</button></form><p class="subtle">${signup?'Already registered? <a href="#/signin">Sign in</a>':'New to LAPENG? <a href="#/signup">Create account</a>'}</p><div class="notice">This local prototype has no email verification or OAuth provider enabled. Do not use real personal data or passwords.</div></div></div></div>`}
const sideLinks=()=>state.mode==='buyer'?[['⌂','Home','/dashboard'],['⌕','Explore','/explore'],['✦','LAPENG AI','/opportunities'],['♡','Saved','/saved'],['🛒','My cart','/cart'],['▣','My orders','/orders'],['◷','Bookings','/bookings'],['✉','Messages','/messages'],['⚙','Settings','/settings'],['♧','Trust centre','/trust']]:[['⌂','Overview','/dashboard'],['▣','My storefront','/provider/new'],['✦','AI invitations','/opportunities'],['▣','Orders & projects','/orders'],['◷','Bookings','/bookings'],['＄','Settlement status','/settlements'],['✉','Messages','/messages'],['♧','Trust centre','/trust'],['⚙','Settings','/settings']];
function shell(content){const sel=path();return `<div class="shell"><aside class="sidebar"><div class="label">WORKSPACE</div><select id="workspace" aria-label="Switch workspace"><option value="buyer" ${state.mode==='buyer'?'selected':''}>Buyer</option><option value="provider" ${state.mode==='provider'?'selected':''}>Provider</option></select>${sideLinks().map(([ic,name,route])=>`<a class="side-link ${sel===route?'active':''}" href="#${route}">${ic} &nbsp;${name}</a>`).join('')}</aside><main class="content">${backBar()}${content}</main></div>`}
function dashboard(){let provider=state.mode==='provider';return shell(`<div class="welcome"><span class="eyebrow">${provider?'PROVIDER':'BUYER'} WORKSPACE</span><h1>Good to see you, ${e(state.user.name.split(' ')[0])}.</h1><p class="subtle">${provider?'Present your work, discover opportunities, and make meaningful connections.':'Find services, ask LAPENG AI for real matches, and message providers privately.'}</p><a class="btn" href="#/${provider?'provider/new':'opportunities'}">${provider?'Create provider profile':'Find providers with AI'} →</a></div><div class="stats"><div class="card stat"><span class="subtle">${provider?'My businesses':'Available providers'}</span><strong>${provider?state.user.businesses.length:state.providers.length}</strong></div><div class="card stat"><span class="subtle">Open opportunities</span><strong>${state.requests.filter(x=>x.status==='open').length}</strong></div><div class="card stat"><span class="subtle">Your requests</span><strong>${state.requests.filter(x=>x.buyer_id===state.user.id).length}</strong></div></div><div class="section-head"><h2>${provider?'Your businesses':'Recommended for you'}</h2><a class="link" href="#/${provider?'provider/new':'explore'}">${provider?'Add another':'See all'} →</a></div>${provider?`<div class="provider-grid">${state.user.businesses.map(pcard).join('')||'<div class="panel">You have no provider profile yet. Create one to start offering services.</div>'}</div>`:`<div class="provider-grid">${state.providers.slice(0,2).map(pcard).join('')||'<div class="panel empty">No providers yet. Create a provider profile to start the community.</div>'}</div>`}<div class="section-head"><h2>Recent opportunities</h2><a href="#/requests" class="link">View all →</a></div><div class="panel">${state.requests.slice(0,4).map(item=>`<div class="list-item"><div><h3>${e(item.title)}</h3><div class="meta">${e(item.city)} · $${item.budget} budget · ${e(item.status)}</div></div><a class="btn ghost small" href="#/requests/${item.id}">View →</a></div>`).join('')||'<p class="subtle">No requests yet. Post the first one!</p>'}</div>`) }
function explore(){const cards=visibleProviders();const real=cards.filter(p=>p.owner_id!==null).length;return `<div class="explore-public"><section class="explore-hero"><div class="explore-title"><span class="eyebrow">EXPLORE LAPENG</span><h1>Discover more. <em>Find your people.</em></h1><p>Shop clothing and everyday essentials, find local businesses, or hire skilled professionals worldwide.</p></div><div class="explore-art"><img src="/static/media/web.webp" alt="Digital professional service"><img src="/static/media/carpentry.webp" alt="Carpentry service"><img src="/static/media/bakery.webp" alt="Bakery service"></div></section><form data-form="search" class="explore-search"><label class="sr-only" for="search-q">Search LAPENG</label><input id="search-q" name="q" value="${e(state.q)}" placeholder="Search clothing, services or a code like LPG-P-000012…"><select name="sort" aria-label="Sort results"><option value="recommended">Recommended</option><option value="rating">Highest rated</option><option value="price">Lowest price</option><option value="new">New</option></select><button class="btn">Search</button></form><div class="lapeng-location-panel"><div><b>Find services near you</b><p class="subtle">${geoText()} · Nearby filters local providers by their published service radius. Remote work remains available in normal search.</p></div><div class="form-actions"><button type="button" class="btn outline small" data-action="near-me">${state.geo?'Refresh nearby':'Use my location'}</button>${state.geo?'<button type="button" class="btn ghost small" data-action="location-clear">Clear</button>':''}</div></div>${categoryChooser()}<div class="explore-section-head"><div><span class="eyebrow">DISCOVER THE COMMUNITY</span><h2>${state.q?'Search results':state.activeCategory?marketplaceCategories.find(x=>x.id===state.activeCategory)?.name:'Explore products, services & businesses'}</h2><p>${real?`${real} community-created listing${real===1?'':'s'} shown first. `:''}Up to six clearly marked examples may appear while the community grows.</p></div>${!state.user?'<a class="explore-signin" href="#/signin">Sign in to hire or offer services →</a>':''}</div><div class="explore-section-head"><div><span class="eyebrow">ACTUAL LISTINGS</span><h2>Products & services</h2><p>Community-created listings only. No invented prices, stock or reviews.</p></div></div><div class="listing-grid commerce-discover-grid">${state.catalogue.filter(l=>(!state.geo||state.providers.some(p=>p.id===l.provider_id))&&(!state.activeCategory||categoryMatch({name:l.title,category:l.catalog_category,skills:l.description,bio:l.description,kind:l.kind},state.activeCategory))).slice(0,24).map(l=>`<article class="panel listing-panel commerce-discover-card shop-product-tile"><a class="shop-tile-image" href="#/product/${l.id}" aria-label="View ${e(l.title)}">${l.photo_url?`<img class="listing-cover" src="${e(l.photo_url)}" alt="${e(l.title)}" loading="lazy">`:'<div class="commerce-photo-empty">No photo uploaded yet</div>'}</a><span class="eyebrow">${e(l.catalog_category||l.kind)}</span><h3><a href="#/product/${l.id}">${e(l.title)}</a></h3><span class="public-ref">${e(l.public_id)}</span><p class="meta">${e(l.provider_name)} · ${e(l.city)}</p><p class="subtle">${e(l.description.slice(0,140))}</p><p><b>${money(l.price,l.currency)}</b></p><a href="#/product/${l.id}" class="btn small outline">${isShopProduct(l.kind)?"View product":"View service"}</a>${state.user?`<button class="btn ghost small" data-action="save-listing" data-id="${l.id}">♡ Save</button>`:''}</article>`).join('')||'<div class="panel"><p class="subtle">No live listings match yet. Browse categories or explore local providers below.</p></div>'}</div><div class="explore-section-head"><div><span class="eyebrow">PEOPLE & BUSINESSES</span><h2>Meet providers</h2></div></div><div class="provider-grid polish-provider-grid" id="results">${cards.map(pcard).join('')||'<div class="panel empty">No matches yet. Try another term or check back as providers join LAPENG.</div>'}</div></div>`}

async function profile(id){let p;try{p=await api('/providers/'+id)}catch(err){return `<div class="page">${e(err.message)}</div>`}let bizSetup={};try{bizSetup=await api('/business-setup/providers/'+id+'/public')}catch(_){}const demo=p.owner_id===null;const isAccountOwner=!!state.user&&p.owner_id===state.user.id;const owner=isAccountOwner&&state.mode==='provider';
const brandAvatar=(p.photos||[]).find(im=>im.role==='avatar');
const brandCover=(p.photos||[]).find(im=>im.role==='cover');
const lookbook=(p.photos||[]).filter(im=>!im.listing_id&&!['avatar','cover'].includes(im.role));
const storeCategory=state.storefrontFilters?.[p.id]||'All';
const storeCategories=[...new Set((p.listings||[]).map(l=>(l.catalog_category||l.kind||'Other').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
const shownListings=storeCategory==='All'?p.listings:p.listings.filter(l=>(l.catalog_category||l.kind||'Other').trim()===storeCategory);
return `<div class="page profile-page">${!isAccountOwner&&!demo?`<div class="lapeng-contact-strip"><button class="btn outline" data-action="message-provider" data-provider="${p.id}">✉ Message ${e(p.name)}</button><span class="hint">Private enquiry · Sign-in required</span></div>`:''}<div class="profile-hero panel storefront-brand-hero"><div class="storefront-cover">${brandCover?`<img src="${e(brandCover.url)}" alt="${e(p.name)} storefront cover" loading="lazy">`:`<div class="storefront-cover-placeholder"><span>${e(p.category)}</span></div>`}</div><div class="storefront-brand-content"><div class="profile-identity"><div class="profile-monogram storefront-brand-avatar">${brandAvatar?`<img src="${e(brandAvatar.url)}" alt="${e(p.name)} business profile picture" loading="lazy">`:e(p.name.slice(0,2).toUpperCase())}</div><div><span class="eyebrow">${e(p.category)}</span><h1 class="page-title">${e(p.name)}</h1><span class="public-ref">${e(p.public_id)}</span><p class="meta">${e(p.city)}, ${e(p.country)} · ${p.remote?'Remote work available':'Local service area'} · ${demo?'Preview example':'Community provider · identity not verified'}</p></div></div>${owner?`<div class="storefront-brand-editor"><div class="storefront-brand-upload"><form data-form="photo" data-provider="${p.id}"><input type="hidden" name="role" value="avatar"><label>Business profile picture or logo</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><input type="hidden" name="caption" value="Business profile picture"><button class="btn outline small">${brandAvatar?'Replace profile picture':'Upload profile picture'}</button></form>${brandAvatar?`<button class="btn ghost small" data-action="delete-photo" data-id="${brandAvatar.id}" data-provider="${p.id}">Remove picture</button>`:''}</div><div class="storefront-brand-upload"><form data-form="photo" data-provider="${p.id}"><input type="hidden" name="role" value="cover"><label>Wide storefront cover photo</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><input type="hidden" name="caption" value="Business cover"><button class="btn outline small">${brandCover?'Replace cover':'Upload cover photo'}</button></form>${brandCover?`<button class="btn ghost small" data-action="delete-photo" data-id="${brandCover.id}" data-provider="${p.id}">Remove cover</button>`:''}</div></div>`:''}<p class="profile-bio">${e(p.bio)}</p>${p.website?`<p class="meta"><a href="${e(p.website)}" target="_blank" rel="noopener noreferrer nofollow">Visit business website ↗</a> <small>(opens the provider’s external website)</small></p>`:''}${!p.remote&&/service/i.test(p.kind)?`<p class="meta">📍 On-site service area: ${e(p.city)}, ${e(p.country)} · ${e(p.service_radius_km)} km from provider's service centre. ${p.latitude==null?'Local bookings unavailable until location is configured.':'Local appointments require an eligible buyer location.'}</p>`:'<p class="meta">Remote services available; check scope and time zone before booking.</p>'}<div class="skills-row">${p.skills.split(',').map(skill=>`<span class="skill-chip">${e(skill.trim())}</span>`).join('')}</div><div class="form-actions">${owner?`<a class="btn" href="#/provider/${p.id}/edit">Edit profile</a><a class="btn outline" href="#/provider/${p.id}/listing/new">Add product or service</a><button class="btn ghost" data-action="delete-provider" data-id="${p.id}">Delete profile</button>`:(isAccountOwner?`<span class="notice">You're viewing your own business in Buyer mode. Switch to Provider to edit your business, products and photos.</span><button class="btn outline" data-action="switch-to-provider">Open Provider workspace</button>`:`<button class="btn" data-action="message-provider" data-provider="${p.id}">${state.user?'Message / request a quote':'Sign in to contact'}</button><button class="btn outline" data-action="report" data-id="${p.id}">Report a concern</button>`)}</div></div></div><section class="profile-section business-contact-panel panel"><div class="section-head"><h2>Contact & availability</h2></div><p class="subtle">${e(bizSetup.customer_notes||'Contact this business using a LAPENG enquiry, or view available services and packages.')}</p>${bizSetup.details&&Object.keys(bizSetup.details).length?`<dl class="business-public-details">${Object.entries(bizSetup.details).filter(([k,v])=>v&&String(v).trim()).map(([k,v])=>`<div><dt>${e(k.replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase()))}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>`:''}${bizSetup.booking_enabled?`<p><b>Appointments:</b> ${e(bizSetup.appointment_policy||'Available by request; provider confirmation required.')}</p>`:''}${bizSetup.business_phone&&['sms','both'].includes(bizSetup.contact_method)?`<a class="btn outline small" href="${state.user?'sms:'+e(bizSetup.business_phone):'#/signin'}">${state.user?'Text owner (opens your messaging app)':'Sign in to text owner'}</a>`:''}<button class="btn outline small" data-action="message-provider" data-provider="${p.id}">${state.user?'Send a private enquiry':'Sign in to contact'}</button>${bizSetup.booking_enabled?`<p class="hint">Choose an available service listing to request an appointment inside LAPENG.</p>`:''}<p class="hint">Contact details and booking policies are provided by the business and are not independently verified.</p></section><section class="profile-section"><div class="section-head"><h2>Lookbook & portfolio</h2><span class="subtle">${lookbook.length} work photo(s)</span></div><p class="subtle">Only work and before/after photos appear here. Individual product photos remain with their own catalogue listings.</p>${owner?`<div class="panel"><form data-form="photo" data-provider="${p.id}"><div class="split"><div class="field"><label>Photograph of your work (JPG, PNG or WebP, up to 10 MB)</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp" required></div><div class="field"><label>Photo type</label><select name="role"><option value="work">Portfolio / completed work</option><option value="before">Before</option><option value="after">After</option></select></div></div><div class="split"><div class="field"><label>Caption</label><input name="caption" maxlength="150" placeholder="Describe the work shown"></div><div class="field"><label>Link to listing (optional)</label><select name="listing_id"><option value="">General portfolio</option>${p.listings.map(l=>`<option value="${l.id}">${e(l.title)}</option>`).join('')}</select></div></div><button class="btn">Upload photograph</button></form></div>`:''}${photoGrid(lookbook,owner,p.id)}</section><section class="profile-section" id="storefront-catalogue"><div class="section-head"><div><span class="eyebrow">${owner?'MY PRODUCT CATALOGUE':'SHOP THIS BUSINESS'}</span><h2>${owner?'Manage your products & services':'Products & services'}</h2><p class="subtle">${p.listings.length} unique product${p.listings.length===1?'':'s'} and service${p.listings.length===1?'':'s'} from this business. Each item has its own photos, options, prices and stock.</p></div>${owner?`<a href="#/provider/${p.id}/listing/new" class="btn small">+ Add another product</a>`:''}</div>${owner?`<div class="storefront-owner-tip"><strong>One business, unlimited variety.</strong> Add shoes, dresses, trousers, handbags or other products separately under this same profile. After publishing one, choose <b>Add another product</b> to continue building your catalogue.</div>`:''}${storeCategories.length>1?`<nav class="storefront-filters" aria-label="Shop by product category"><button class="storefront-filter ${storeCategory==='All'?'active':''}" data-action="storefront-filter" data-provider="${p.id}" data-category="All" aria-pressed="${storeCategory==='All'}">All (${p.listings.length})</button>${storeCategories.map(c=>`<button class="storefront-filter ${storeCategory===c?'active':''}" data-action="storefront-filter" data-provider="${p.id}" data-category="${e(c)}" aria-pressed="${storeCategory===c}">${e(c)} (${p.listings.filter(l=>(l.catalog_category||l.kind||'Other').trim()===c).length})</button>`).join('')}</nav>`:''}<div class="listing-grid storefront-grid">${shownListings.map(l=>`<article class="panel listing-panel shop-product-tile storefront-product-tile"><a class="shop-tile-image" href="#/product/${l.id}" aria-label="Open ${e(l.title)}">${l.photos[0]?`<img class="listing-cover" src="${e(l.photos[0].url)}" alt="${e(l.title)}" loading="lazy">`:'<div class="product-photo-placeholder">Photo coming soon</div>'}</a><div class="shop-tile-info"><span class="eyebrow">${e(l.catalog_category||l.kind)}</span><h3><a href="#/product/${l.id}">${e(l.title)}</a></h3><div class="shop-tile-price">${l.price?money(l.price,l.currency):'Request a quote'}</div><p class="meta">${l.reviews?`★ ${Number(l.rating).toFixed(1)} · ${l.reviews} verified reviews`:'New listing · No reviews yet'}</p><a class="btn outline small" href="#/product/${l.id}">View details & options</a>${owner?`<details class="shop-owner-tools"><summary>Manage product & photos</summary>${owner?`<div class="product-photo-manager"><strong>Product photographs (${(l.photos||[]).length}/8)</strong><div class="product-photo-actions">${(l.photos||[]).map(im=>`<div class="product-photo-action"><img src="${e(im.url)}" alt="${e(im.caption||l.title)}"><button class="btn ghost small" data-action="delete-photo" data-provider="${p.id}" data-id="${im.id}" aria-label="Delete photo from ${e(l.title)}">Remove</button></div>`).join('')}</div><form data-form="product-photos" data-provider="${p.id}" data-listing="${l.id}"><label>Add more photos to this product</label><input type="file" name="images" accept="image/jpeg,image/png,image/webp" multiple required><input name="caption" maxlength="150" placeholder="Optional photo caption"><button class="btn outline small">Upload to this product</button></form></div><div class="form-actions"><a class="btn outline small" href="#/provider/${p.id}/listing/${l.id}/edit">Edit</a><button class="btn ghost small" data-action="delete-listing" data-id="${l.id}" data-provider="${p.id}">Delete</button></div>`:''}</details>`:''}</div></article>`).join('')||'<div class="panel">No products or services listed yet.</div>'}</div>${owner?`<div class="storefront-add-more"><a class="btn" href="#/provider/${p.id}/listing/new">+ Add another product or service</a><p class="hint">All products stay under ${e(p.name)}. No new business profile is needed.</p></div>`:''}</section><section class="profile-section"><div class="section-head"><h2>Verified customer feedback</h2><span class="subtle">${p.reviews?`★ ${Number(p.rating).toFixed(1)} / 5 · ${p.reviews} review(s)`:'No reviews yet'}</span></div><div class="review-list">${(p.feedback||[]).map(r=>`<article class="panel"><b>★ ${e(r.score)} / 5</b>${r.listing_title?`<p class="meta">For: ${e(r.listing_title)}</p>`:'<p class="meta">Provider-level feedback</p>'}<p>${e(r.text)}</p></article>`).join('')||'<div class="panel"><p class="subtle">Verified customer feedback will appear after completed eligible transactions. No fictional reviews.</p></div>'}</div></section>${demo?'<div class="notice">This is a fictional example. It is not a verified business, and sample listings cannot accept payments.</div>':''}</div>`}

const productViewState={};

// The editor stores 'Products' (plural); older records may store 'product'.
function isShopProduct(kind){return ['product','products','digital product','digital products'].includes(String(kind||'').trim().toLowerCase());}
function uniqueValues(variants,key){return [...new Set(variants.map(v=>Object.entries(v.options||{}).find(([k])=>k.toLowerCase()===key.toLowerCase())?.[1]).filter(Boolean))]}
function productOption(v,key){return Object.entries(v.options||{}).find(([k])=>k.toLowerCase()===key.toLowerCase())?.[1]||''}
async function productPage(rawId){
 const id=Number(rawId);if(!Number.isSafeInteger(id))return '<div class="page"><h1>Invalid product</h1></div>';
 const base=state.catalogue.find(x=>x.id===id);let p=null;
 if(base)p=await api('/providers/'+base.provider_id);
 if(!p){const candidates=state.providers.filter(x=>x.owner_id!==null);for(const c of candidates){const v=await api('/providers/'+c.id);if((v.listings||[]).some(l=>l.id===id)){p=v;break;}}}
 if(!p)return '<div class="page"><h1>Product not found</h1><a class="btn outline" href="#/explore">Browse LAPENG</a></div>';
 const l=(p.listings||[]).find(x=>x.id===id);if(!l)return '<div class="page"><h1>Product not available</h1></div>';
 const pics=l.photos||[];const vars=l.variants||[];const available=vars.filter(v=>Number(v.stock)>0);
 const current=productViewState[id]||(productViewState[id]={photo:0,pick:{}});
 const first=available[0];if(first&&!Object.keys(current.pick).length)current.pick={...(first.options||{})};
 const keys=[...new Set(vars.flatMap(v=>Object.keys(v.options||{})))];
 const chosen=vars.find(v=>Object.entries(current.pick).every(([k,val])=>!val||productOption(v,k)===val)&&Object.entries(v.options||{}).every(([k,val])=>!current.pick[k]||current.pick[k]===val));
 const productIsReady=!vars.length||!!(chosen&&chosen.stock>0);
 const selectedPrice=chosen?chosen.price:l.price;const selectedStock=chosen?chosen.stock:l.stock;
 const owned=!!state.user&&p.owner_id===state.user.id;
 const canManage=owned&&state.mode==='provider';
 const ownBuyerPreview=owned&&state.mode==='buyer';
 const optionsMarkup=keys.map(key=>{const vals=uniqueValues(vars,key);return `<div class="shop-option-row"><div class="shop-option-heading"><b>${e(key)}</b><span>${e(current.pick[key]||'Choose '+key.toLowerCase())}</span></div><div class="shop-option-pills">${vals.map(val=>{const eligible=vars.some(v=>productOption(v,key)===val&&v.stock>0&&Object.entries(current.pick).every(([k,s])=>k===key||!s||productOption(v,k)===s));return `<button type="button" class="shop-choice ${current.pick[key]===val?'active':''}" data-action="product-option" data-id="${id}" data-key="${e(key)}" data-value="${e(val)}" aria-pressed="${current.pick[key]===val}" ${eligible?'':'disabled'}>${e(val)}</button>`}).join('')}</div></div>`}).join('');
 const image=pics.length?pics[Math.min(current.photo,pics.length-1)]:null;
 return `<div class="page shop-product-page"><nav class="shop-breadcrumb"><a href="#/explore">Explore</a> <span>›</span><a href="#/provider/${p.id}">${e(p.name)}</a><span>›</span>${e(l.title)}</nav><div class="shop-detail-layout"><section class="shop-image-gallery"><div class="shop-gallery-main">${image?`<img src="${e(image.url)}" alt="${e(image.caption||l.title)}">`:'<div class="product-photo-placeholder">No product image uploaded</div>'}</div>${pics.length>1?`<div class="shop-gallery-thumbs">${pics.map((im,n)=>`<button type="button" class="shop-thumb ${n===current.photo?'active':''}" data-action="product-photo" data-id="${id}" data-index="${n}" aria-label="Show image ${n+1}"><img src="${e(im.url)}" alt="${e(im.caption||l.title)}"></button>`).join('')}</div>`:''}</section><section class="shop-product-purchase"><span class="eyebrow">${e(l.catalog_category||l.kind)}</span><h1>${e(l.title)}</h1><p class="meta">Sold by <a href="#/provider/${p.id}">${e(p.name)}</a> · ${e(l.public_id)}</p><p class="meta">${l.reviews?`★ ${Number(l.rating).toFixed(1)} / 5 · ${l.reviews} verified review(s)`:'No verified reviews yet'}</p><div class="shop-product-price">${selectedPrice?money(selectedPrice,l.currency):'Price on quotation'}</div><p class="shop-short-description">${e(l.description)}</p>${optionsMarkup}${(l.packages||[]).length?`<label for="package-${id}"><b>Service package</b></label><select id="package-${id}">${l.packages.map(x=>`<option value="${e(x.name)}">${e(x.name)} · ${money(x.price,l.currency)}</option>`).join('')}</select>`:''}<div class="shop-stock-note ${productIsReady?'':'unavailable'}">${productIsReady?`${Number(selectedStock)} available for this selection`:'This option is currently unavailable'}</div><div class="shop-purchase-row"><label for="qty-${id}">Quantity</label><input type="number" id="qty-${id}" min="1" max="${Math.max(1,Number(selectedStock)||1)}" value="1" ${productIsReady?'':'disabled'}><select id="variant-${id}" class="sr-only" aria-label="Selected variant">${chosen?`<option value="${e(chosen.sku||chosen.name)}">${e(chosen.name)}</option>`:''}</select></div><div class="shop-main-actions">${!owned&&p.owner_id!==null?`<button type="button" class="btn outline" data-action="message-provider" data-provider="${p.id}" data-listing="${id}">✉ Message seller</button>`:''}${canManage?`<a class="btn" href="#/provider/${p.id}/listing/${id}/edit">Edit your listing</a><button class="btn outline" type="button" data-action="switch-workspace" data-mode="buyer">View in Buyer mode</button>`:ownBuyerPreview?`<button type="button" class="btn shop-add-cart" disabled title="Use a separate buyer account to test purchases">${isShopProduct(l.kind)?'Add to bag · Your own listing':'Your own service'}</button><a href="#/explore" class="btn outline">Shop other sellers</a>`:!isShopProduct(l.kind)?`<button type="button" class="btn" data-action="message-provider" data-provider="${p.id}" data-listing="${id}">Message about this service</button><a class="btn outline" href="#/bookings/new?listing=${id}">Request an appointment</a>`:`<button type="button" class="btn shop-add-cart" data-action="cart-add" data-listing="${id}" ${!productIsReady||!Number(selectedStock)?'disabled':''}>Add to bag</button><button type="button" class="btn outline" data-action="save-listing" data-id="${id}">♡ Save</button>`}</div><div class="shop-purchase-note">${ownBuyerPreview?"This is your own listing. Buyer mode is read-only, and you cannot buy from yourself. Sign in with a separate buyer account to test checkout.":"Checkout requires sign-in. PayPal Sandbox payments only; shipping and eligibility are checked at checkout."}</div></section></div><section class="shop-product-extras"><h2>Product information</h2>${catalogInfo(l)}<h2>Shop from this provider</h2><p><a class="btn outline" href="#/provider/${p.id}">View ${e(p.name)} storefront</a></p></section></div>`;
}
const examplesByKind={
  'Fashion & footwear':'Material: Cotton\nFit: Relaxed\nCare: Machine wash cold\nSize guide: Measurements in cm',
  'Beauty & personal care':'Brand: \nVolume: 50 ml\nIngredients: \nSkin type: \nExpiry / PAO:',
  'Electronics & phones':'Brand: \nModel: \nStorage: \nWarranty: \nCondition:',
  'Furniture & home':'Width: 120 cm\nHeight: 80 cm\nDepth: 40 cm\nMaterial: \nAssembly required: Yes',
  'Food & groceries':'Net weight: \nIngredients: \nAllergens: \nStorage instructions:',
  'Freelance & digital':'Technology: \nScope: \nClient requirements: \nFiles delivered:',
  'Other':'Brand: \nMaterial: \nDimensions: '
};
function linePairs(text){const out={};(text||'').split(/\n/).map(x=>x.trim()).filter(Boolean).forEach((line)=>{let n=line.indexOf(':');if(n<1)throw Error('Each detail must be written as Label: Value');let k=line.slice(0,n).trim(),v=line.slice(n+1).trim();if(!k||!v)throw Error('Add both a name and value for every detail');out[k]=v});return out}
function formatPairs(o){return Object.entries(o||{}).map(([k,v])=>`${k}: ${v}`).join('\n')}
function validateProductPhotos(files,existing=0){if(!files.length)return;if(files.length+existing>8)throw Error('Each product supports up to 8 photos. Remove older photos before adding more.');for(const file of files){if(file.size>10485760)throw Error('Each original photo must be 10 MB or smaller.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Only JPG, PNG and WebP product images are supported.')}}
function parseVariants(text){return (text||'').split('\n').filter(x=>x.trim()).map((line,i)=>{const a=line.split('|').map(x=>x.trim());if(a.length!==4)throw Error(`Variant row ${i+1}: use Options | Price | Stock | SKU`);const options=linePairs(a[0].split(';').join('\n'));const price=Number(a[1]),stock=Number(a[2]);if(!Number.isInteger(price)||!Number.isInteger(stock))throw Error('Variant price and stock must be whole numbers');return {name:Object.entries(options).map(([k,v])=>`${k}: ${v}`).join(' / '),options,price,stock,sku:a[3]}})}
function formatVariants(items){return (items||[]).map(x=>`${Object.entries(x.options||{}).map(([k,v])=>`${k}: ${v}`).join('; ')} | ${x.price} | ${x.stock} | ${x.sku||''}`).join('\n')}
function parsePackages(text){return (text||'').split('\n').filter(x=>x.trim()).map((line,i)=>{const a=line.split('|').map(x=>x.trim());if(a.length!==6)throw Error(`Package row ${i+1}: use Name | Price | Days | Revisions | Deliverables | Description`);let price=Number(a[1]),delivery_days=Number(a[2]),revisions=Number(a[3]);if(![price,delivery_days,revisions].every(Number.isInteger))throw Error('Package prices, days and revisions must be whole numbers');return {name:a[0],price,delivery_days,revisions,deliverables:a[4],description:a[5]}})}
function formatPackages(items){return (items||[]).map(x=>`${x.name} | ${x.price} | ${x.delivery_days} | ${x.revisions} | ${x.deliverables||''} | ${x.description||''}`).join('\n')}
function catalogInfo(l){const specs=Object.entries(l.specs||{});const variants=l.variants||[];const packages=l.packages||[];const fulfil=Object.entries(l.fulfilment||{});return `<div class="catalog-information">${specs.length?`<details open><summary>Details & specifications</summary><dl class="catalog-specs">${specs.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></details>`:''}${variants.length?`<details open><summary>Available options · ${variants.length}</summary><div class="catalog-choices">${variants.map(v=>`<div class="catalog-option"><b>${e(v.name)}</b><span>${money(v.price,l.currency)}</span><small>${v.stock>0?`${e(v.stock)} in stock`:'Out of stock'} · ${e(v.sku||'No seller SKU')}</small></div>`).join('')}</div></details>`:''}${packages.length?`<details open><summary>Service packages · ${packages.length}</summary><div class="catalog-choices">${packages.map(x=>`<div class="catalog-option"><b>${e(x.name)}</b><span>${money(x.price,l.currency)}</span><small>${e(x.delivery_days)} days · ${e(x.revisions)} revisions</small><p>${e(x.deliverables)}</p><p>${e(x.description)}</p></div>`).join('')}</div></details>`:''}${fulfil.length?`<details><summary>Delivery, returns & fulfilment</summary><dl class="catalog-specs">${fulfil.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></details>`:''}</div>`}
function listingForm(p,l=null){if(!state.user||p.owner_id!==state.user.id)return mustSign();return shell(`<span class="eyebrow">${l?'EDIT LISTING':'NEW LISTING'}</span><h1 class="page-title">${l?'Edit your offering':'Create a product or service listing'}</h1><p class="subtle">Describe what customers actually need to know. Clothing can use sizes/colours; phones can list storage and warranties; freelancers can offer packages.</p><div class="panel listing-editor"><form data-form="listing" data-provider="${p.id}" ${l?`data-listing="${l.id}"`:''}><div class="field"><label>Product or service name</label><input name="title" value="${e(l?.title||'')}" minlength="3" maxlength="130" required placeholder="e.g. Linen summer dress / Business website design"></div><div class="field"><label>Full description</label><textarea name="description" minlength="10" required placeholder="Describe the item, quality, who it's for, and what's included">${e(l?.description||'')}</textarea></div><div class="split"><div class="field"><label>Offering type</label><select name="kind">${['Products','Services','Digital products','Digital services','Rentals','Local services'].map(k=>`<option ${l?.kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Specific category</label><input name="catalog_category" value="${e(l?.catalog_category||p.category)}" list="catalog-categories" maxlength="80" placeholder="Fashion & footwear"><datalist id="catalog-categories">${Object.keys(examplesByKind).map(v=>`<option value="${e(v)}">`).join('')}</datalist></div></div><div class="split"><div class="field"><label>Starting price (0 for quotation)</label><input name="price" type="number" min="0" value="${l?.price??0}" required></div><div class="field"><label>Currency</label><select name="currency">${["USD","ZAR","EUR","GBP","CAD","AUD","NZD"].map(c=>`<option value="${c}" ${((l?.currency||"USD")===c)?"selected":""}>${c}</option>`).join("")}</select></div><div class="field"><label>General stock or capacity</label><input name="stock" type="number" min="0" value="${l?.stock??1}" required></div></div><fieldset class="catalog-fieldset"><legend>Specifications</legend><p class="hint">One <b>Label: Value</b> per line. For fashion, include fabric, care and size guide; for phones, storage and warranty; for furniture, dimensions and materials.</p><textarea name="specs_text" rows="6" placeholder="Material: 100% cotton&#10;Care: Machine wash cold&#10;Fit: Relaxed">${e(formatPairs(l?.specs||{}))}</textarea></fieldset><fieldset class="catalog-fieldset"><legend>Variations — sizes, colours, storage, shades or finishes</legend><p class="hint">Optional. Each line: <b>Size: M; Colour: Black | 35 | 8 | DRESS-M-BLK</b>. Enter a separate line for every combination, with its own price and stock. Do not enter unavailable combinations.</p><textarea name="variants_text" rows="5" placeholder="Size: S; Colour: Black | 35 | 4 | DRESS-S-BLK&#10;Size: M; Colour: Black | 35 | 8 | DRESS-M-BLK">${e(formatVariants(l?.variants||[]))}</textarea></fieldset><fieldset class="catalog-fieldset"><legend>Service packages</legend><p class="hint">Optional for freelancers, trades and professional services. One line: <b>Starter | 120 | 7 | 2 | One landing page | Responsive design with handover</b>. Format: name, price, delivery days, revisions, deliverables, description.</p><textarea name="packages_text" rows="4" placeholder="Starter | 120 | 7 | 2 | One landing page | Responsive design and handover">${e(formatPackages(l?.packages||[]))}</textarea></fieldset><fieldset class="catalog-fieldset"><legend>Delivery, fulfilment and policies</legend><p class="hint">One <b>Label: Value</b> per line. State accurate delivery areas, collection options, timelines and return conditions.</p><textarea name="fulfilment_text" rows="4" placeholder="Delivery: Johannesburg local courier&#10;Returns: Contact seller before purchase">${e(formatPairs(l?.fulfilment||{}))}</textarea></fieldset><fieldset class="catalog-fieldset"><legend>Photos for this specific product or service</legend><p class="hint">Choose up to 8 JPG, PNG or WebP photos (10 MB per original photo). The most recently uploaded photo appears as the main catalogue image. Add front, back, detail or colour views. These photos belong to this listing, not your business lookbook.</p><input type="file" name="product_images" accept="image/jpeg,image/png,image/webp" multiple><label for="product-photo-caption">Optional caption for new photos</label><input id="product-photo-caption" name="product_photo_caption" maxlength="150" placeholder="e.g. Front and detail views of burgundy dress">${l?`<p class="hint">This listing already has ${(l.photos||[]).length} photo(s). Use the buttons on the business storefront to remove individual images.</p>`:''}</fieldset><div class="notice">Images are uploaded to the specific product after its details are saved. Payments remain subject to PayPal Sandbox support; seller payouts are not yet connected.</div><button class="btn">${l?'Save listing':'Publish listing'}</button></form></div>`)}

function requestForm(){return shell(`<div class="panel narrow"><span class="eyebrow">PRIVATE AI MATCHING</span><h1>Tell LAPENG what you need</h1><p>Requests are analysed privately by Opportunity AI and matched to real provider listings. Nothing is posted publicly.</p><a class="btn" href="#/opportunities">Start with LAPENG AI →</a></div>`)}
function requests(){return shell(`<span class="eyebrow">OPPORTUNITIES</span><h1 class="page-title">Legacy requests</h1><p class="subtle">Existing project requests remain available for reference. New customer needs are handled privately by LAPENG Opportunity AI.</p><div class="form-actions"><a class="btn" href="#/opportunities">✦ Ask LAPENG AI</a></div><div class="panel" style="margin-top:18px">${state.requests.map(r=>`<div class="list-item"><div><h3>${e(r.title)}</h3><span class="public-ref">${refId('R',r.id)}</span><p class="meta">${e(r.buyer_name)} · ${e(r.city)} · ${r.quantity} unit(s) · $${r.budget} budget · ${e(r.status)}</p></div><a class="btn ghost small" href="#/requests/${r.id}">Open →</a></div>`).join('')||'<div class="empty">No requests yet. Start with one, then test LAPENG’s coalition planner.</div>'}</div>`)}
async function detailRequest(id){if(!state.user)return mustSign();let r;try{r=await api('/requests/'+id)}catch(err){return `<div class="page">${e(err.message)}</div>`}const mine=r.buyer_id===state.user.id;const owns=state.user.businesses||[];return shell(`<span class="eyebrow">PROJECT WORKSPACE · ${refId('R',r.id)}</span><h1 class="page-title">${e(r.title)}</h1><p class="subtle">Posted by ${e(r.buyer_name)} · ${e(r.city)} · ${r.quantity} unit(s) · Budget $${r.budget} USD · ${e(r.status)}</p><div class="split"><div><div class="panel"><h3>Project brief</h3><p class="subtle">${e(r.description)}</p><h3>Proposals</h3>${r.proposals.map(p=>`<div class="list-item"><div><b>${e(p.provider_name)}</b><p class="meta">${refId('Q',p.id)} · $${p.amount} · ${e(p.status)} · ${e(p.note)}</p></div>${mine&&r.status==='open'?`<button class="btn small" data-action="accept" data-id="${p.id}">Accept</button>`:''}</div>`).join('')||'<p class="subtle">No quotes yet.</p>'}</div>${!mine&&owns.length?`<div class="panel" style="margin-top:16px"><h3>Send a quote</h3><form data-form="proposal" data-request="${r.id}"><div class="field"><label>Which business?</label><select name="provider_id">${owns.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label>Total price in USD</label><input name="amount" type="number" min="1" required></div><div class="field"><label>Scope and commitments</label><textarea name="note" required minlength="4"></textarea></div><button class="btn">Send quote</button></form></div>`:''}${mine?`<div class="panel" style="margin-top:16px"><h3>Financial protection</h3><p class="subtle">Only accepted proposals can proceed to PayPal Sandbox checkout. You must approve payment on PayPal's site; a screenshot is not payment verification.</p>${r.proposals.filter(p=>p.status==='accepted').map(p=>`<button class="btn" data-action="paypal" data-id="${p.id}">Pay $${p.amount} with PayPal Sandbox →</button>`).join('')}${r.payments.map(p=>`<p class="notice ${p.status==='COMPLETED'?'good':''}">${refId('T',p.id)}: ${e(p.status)} · ${e(p.currency)} ${p.amount} ${p.status==='COMPLETED'?`<button class="btn small" data-action="review" data-id="${p.id}">Review provider</button>`:''}</p>`).join('')}</div>`:''}</div><div><div class="panel"><h3>LAPENG Intelligence</h3><p class="subtle">Capacity-aware matching, a deterministic coalition allocation and optional real AI explanations. No merchant is committed by an algorithm.</p><button class="btn" data-action="assemble" data-id="${r.id}">Assemble opportunity →</button><div id="intelligence" style="margin-top:14px"></div></div><div class="panel" style="margin-top:16px"><h3>Project conversation</h3><div class="chat">${r.messages.map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}"><small>${e(m.sender_name)}</small>${e(m.body)}</div>`).join('')||'<p class="subtle">Messages become available to the buyer and participating providers.</p>'}</div>${mine||r.proposals.some(p=>p.provider_owner===state.user.id&&p.status==='accepted')?`<form data-form="message" data-request="${r.id}" class="form-actions"><input class="input" style="flex:1" name="body" required maxlength="1500" placeholder="Write a message…"><button class="btn">Send</button></form>`:''}</div><div class="panel" style="margin-top:16px"><h3>Guardian</h3><p class="subtle">Flag suspicious off-platform payment attempts. Warnings are signals, not fraud verdicts.</p><button class="btn ghost" data-action="guardian" data-id="${r.id}">Run safety check</button><div id="guardian"></div></div></div></div>`)}
