   await api('/operations/providers/'+finalPid+'/schedule',{method:'PUT',body:JSON.stringify({timezone:d.timezone||'Africa/Johannesburg',hours,slot_minutes:Number(d.slot_minutes||60),lead_hours:Number(d.lead_hours||2),break_minutes:0})});
