function switchWorkspace(next){
  if(!state.user){go('/signin');return;}
  if(!['buyer','provider'].includes(next))return;
  state.mode=next;
  localStorage.setItem('lapeng_mode',next);
  document.documentElement.classList.add('lapeng-workspace-changing');
  // Navigate to the relevant dashboard rather than leaving a provider editing page open in Buyer mode.
  if(path().split('?')[0]==='/dashboard'){void render().finally(()=>document.documentElement.classList.remove('lapeng-workspace-changing'));}
  else {go('/dashboard');document.documentElement.classList.remove('lapeng-workspace-changing');}
  toast(next==='buyer'?'Buyer workspace ready. Browse other sellers and add their products to your cart.':'Provider workspace ready. Manage your listings and orders here.');
}
async function act(ev){const b=ev.target.closest('[data-action]');if(!b)return;const id=+b.dataset.id;try{switch(b.dataset.action){case 'mobile-menu':{const top=b.closest('.top');const opened=top.classList.toggle('mobile-nav-open');b.setAttribute('aria-expanded',String(opened));b.setAttribute('aria-label',opened?'Close navigation menu':'Open navigation menu');break;}
case 'navigate-back':navigateBack();break;
case 'switch-workspace':switchWorkspace(b.dataset.mode);break;
case 'product-photo':{const x=productViewState[id];if(x){x.photo=Number(b.dataset.index)||0;await render();}break;}
case 'product-option':{const x=productViewState[id];if(x){x.pick[b.dataset.key]=b.dataset.value;await render();}break;}
case 'op-choose':{if(!await lapengConfirm('Invite this real provider to discuss this part of your plan? No booking or charge will occur.'))break;await api('/opportunities/plans/'+b.dataset.plan+'/parts/'+id+'/choose',{method:'POST',body:JSON.stringify({listing_id:+b.dataset.listing})});toast('Provider invited in LAPENG. Await their reply.');await render();break;}
case 'op-recover':{if(!await lapengConfirm('Reopen the declined request to consider alternative providers? No one will be invited automatically.'))break;const result=await api('/opportunities/plans/'+b.dataset.plan+'/parts/'+id+'/recover',{method:'POST'});toast('Reopened. '+result.alternatives.length+' other eligible options currently available.');await render();break;}
case 'op-link-order':{const raw=await lapengPrompt('Enter the number of your completed PayPal Sandbox order (found under My orders). This only links an actual paid order for the accepted listing:');if(raw===null)break;const orderId=Number(raw.trim());if(!Number.isSafeInteger(orderId)||orderId<1)throw Error('Enter a valid order number');const proof=await api('/opportunities/plans/'+b.dataset.plan+'/parts/'+id+'/link-order',{method:'POST',body:JSON.stringify({order_id:orderId})});toast('Verified paid order #'+proof.order_id+' linked to your plan.');await render();break;}
case 'op-respond':{const accept=b.dataset.accept==='yes';const note=await lapengPrompt(accept?'Optional message to the customer:':'Optional reason for declining:');if(note===null)break;await api('/opportunities/invitations/'+id+'/respond',{method:'POST',body:JSON.stringify({accept,note})});toast('Your decision has been recorded. No payment was made.');await render();break;}
case 'op-cart':{const listing=state.catalogue?.find(l=>l.id===+b.dataset.listing);if(b.dataset.kind!=='product'||!listing||!isShopProduct(listing.kind))throw Error('Only physical products can be added to cart from an opportunity plan. Contact the service provider instead.');await api('/commerce/cart',{method:'POST',body:JSON.stringify({listing_id:+b.dataset.listing,option:'',quantity:1})});await updateCartCount();toast('Added to your bag.');go('/cart');break;}
case 'request-location-review':{const x=await api('/operations/providers/'+id+'/verification/request',{method:'POST'});toast('Location review requested. A moderator must check independent evidence.');await render();break;}
case 'calendar-export':{const res=await fetch('/api/operations/bookings/'+id+'/calendar.ics',{headers:{Authorization:'Bearer '+state.token}});if(!res.ok)throw Error('Could not export appointment');const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lapeng-booking-'+id+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break;}
case 'load-slots':{const day=$('#slot-day')?.value;if(!day){toast('Select a date first.');break;}const x=await api('/operations/providers/'+b.dataset.provider+'/slots?day='+encodeURIComponent(day));const select=$('#slot-options');select.innerHTML='<option value="">Choose an available time</option>'+x.slots.map(slot=>`<option value="${slot.start}:${slot.end}">${e(slot.label)} (${e(x.timezone)})</option>`).join('');if(!x.slots.length)toast('No available slots on that date.');break;}

case 'near-me':{state.geo=await askLocation();state.geoStatus='Nearby search enabled';await nearbyRefresh();await render();toast('Showing local providers who cover your current area.');break;}
case 'location-clear':{state.geo=null;state.providers=await api('/providers');await render();toast('Location cleared from this tab.');break;}
case 'provider-use-location':{const g=await askLocation();const form=b.closest('form');if(!form){toast('Open the provider form to set your location.');break;}form.querySelector('[name=latitude]').value=g.latitude.toFixed(5);form.querySelector('[name=longitude]').value=g.longitude.toFixed(5);toast('Service-area centre entered. Save your profile to publish it.');break;}
case 'booking-use-location':{state.geo=await askLocation();const el=$('#booking-location-status');if(el)el.textContent=geoText();toast('Location captured for this booking request only.');break;}

case 'edit-checkout-address':state.checkoutAddressEditing=true;await render();document.getElementById('lapeng-delivery-address')?.focus();break;
case 'order-edit-address':{const order=await api('/commerce/orders/'+id);if(order.buyer_id!==state.user.id)throw Error('Only the buyer can change this order address.');if(!['pending','processing','unfulfilled','not_shipped','awaiting_fulfilment'].includes(String(order.fulfilment_status||'').toLowerCase()))throw Error('The order is already shipped or cannot be edited.');const address=await lapengPrompt('New full delivery address (changes must be approved and saved before shipment):',order.delivery_address||'');if(address===null)break;if(address.trim().length<12)throw Error('Enter a complete shipping address.');await api('/commerce/orders/'+id+'/delivery-address',{method:'PATCH',body:JSON.stringify({delivery_address:address.trim()})});toast('Order delivery address updated.');await render();break;}
case 'cart-add':{if(!state.user){go('/signin');break;}const lid=+b.dataset.listing;const item=state.catalogue.find(l=>l.id===lid);if(item&&!isShopProduct(item.kind))throw Error('Services use provider messages and requests, not the shopping cart.');if(item&&state.user.businesses?.some(p=>p.id===item.provider_id))throw Error('You cannot buy your own listing. Use a separate buyer account.');const variant=$('#variant-'+lid)?.value||'',pkg=$('#package-'+lid)?.value||'';const qty=+($('#qty-'+lid)?.value||1);await api('/commerce/cart',{method:'POST',body:JSON.stringify({listing_id:lid,option:variant||pkg,quantity:qty})});await updateCartCount();toast('Added to your bag.');go('/cart');break}
case 'cart-step':{const input=document.querySelector(`[data-cart-quantity="${id}"]`);if(!input)break;const step=Number(b.dataset.step)||0;const next=Number(input.value)+step;const max=Number(input.max)||100;if(!Number.isInteger(next)||next<1||next>max)break;const option=document.querySelector(`[data-cart-variant="${id}"]`)?.value||'';b.disabled=true;try{await api('/commerce/cart/'+id,{method:'PATCH',body:JSON.stringify({choice:option,quantity:next})});await updateCartCount();await render()}finally{b.disabled=false}break;}
case 'cart-update':{const option=document.querySelector(`[data-cart-variant="${id}"]`)?.value||'';const qty=Number(document.querySelector(`[data-cart-quantity="${id}"]`)?.value);if(!Number.isInteger(qty)||qty<1||qty>100)throw Error('Enter a valid quantity from 1 to 100');b.disabled=true;try{await api('/commerce/cart/'+id,{method:'PATCH',body:JSON.stringify({choice:option,quantity:qty})});await updateCartCount();toast('Your bag has been updated.');await render()}finally{b.disabled=false}break;}
case 'cart-remove':await api('/commerce/cart/'+id,{method:'DELETE'});await updateCartCount();toast('Item removed from your bag.');await render();break;
case 'booking-start':go(state.user?'/bookings/new?listing='+b.dataset.listing:'/signin');break;
case 'print-receipt':window.print();break;
case 'aftercare-decision':{const note=await lapengPrompt('Reason for decision (optional)');if(note===null)break;await api('/aftercare/cases/'+id+'/decision',{method:'POST',body:JSON.stringify({decision:b.dataset.status,note})});toast('Decision recorded. No refund or replacement has been issued.');await render();break;}
case 'reschedule-decide':await api('/aftercare/reschedules/'+id+'/decision',{method:'POST',body:JSON.stringify({decision:b.dataset.status})});toast('Booking change reviewed.');await render();break;
case 'booking-status':await api('/commerce/bookings/'+id+'/status',{method:'POST',body:JSON.stringify({status:b.dataset.status})});await render();break;
case 'return-decision':await api('/commerce/returns/'+id+'/decision',{method:'POST',body:JSON.stringify({status:b.dataset.status})});await render();toast('Return reviewed. An approved return is reviewed by the platform operator before an actual Sandbox refund.');break;
case 'milestone':await api('/commerce/milestones/'+id+'/status',{method:'POST',body:JSON.stringify({status:b.dataset.status,note:''})});await render();break;
case 'storefront-filter':{const pid=Number(b.dataset.provider);if(!state.storefrontFilters)state.storefrontFilters={};state.storefrontFilters[pid]=b.dataset.category||'All';await render();document.getElementById('storefront-catalogue')?.scrollIntoView({block:'start'});break;}
case 'save-listing':{if(!state.user){go('/signin');break;}await api('/commerce/saved/'+id,{method:'POST'});toast('Saved to your shortlist');break;}
case 'unsave':{await api('/commerce/saved/'+id,{method:'DELETE'});toast('Removed from saved items');await render();break;}
case 'order-review':{const score=Number(await lapengPrompt('Rate this item or service from 1 to 5'));if(!score)return;const text=await lapengPrompt('Describe your experience (minimum eight characters)');if(!text)return;await api('/commerce/orders/'+id+'/reviews',{method:'POST',body:JSON.stringify({listing_id:+b.dataset.listing,score,text})});toast('Verified item review published.');await render();break;}
case 'logout':try{await api('/auth/logout',{method:'POST'})}catch(err){}state.token='';state.user=null;sessionStorage.removeItem('lapeng_token');go('/');break;case 'category-filter':state.activeCategory=state.activeCategory===b.dataset.category?'':(b.dataset.category||'');state.q='';state.backendSearch=false;state.providers=await api('/providers');if(path().split('?')[0]==='/explore')await render();else go('/explore');break;case 'profile':go('/provider/'+id);break;
case 'request-listing':case 'message-provider':{
 if(!state.user){go('/signin');break;}
 const pid=Number(b.dataset.provider), lid=b.dataset.listing?Number(b.dataset.listing):null;
 const provider=await api('/providers/'+pid);
 if(!provider||provider.owner_id==null)throw Error('This is a sample business. Messaging is available for real provider accounts.');
 if(provider.owner_id===state.user.id)throw Error('You cannot message your own business. Use a separate buyer account to test.');
 const listing=lid?(provider.listings||[]).find(l=>l.id===lid):null;
 if(lid&&!listing)throw Error('Service or product not found');
 const initial=listing?`Hi, I'm interested in ${listing.title}. Could you tell me about availability, pricing and next steps?`:`Hi, I found ${provider.name} on LAPENG and would like to enquire about your services.`;
 const message=await lapengPrompt('Your message will be private between you and '+provider.name+'.',initial,{title:'Message '+provider.name,label:'Message',required:true,minLength:2});
 if(message===null)break;if(message.trim().length<2)throw Error('Write a message of at least two characters');
 const thread=await api('/conversations',{method:'POST',body:JSON.stringify({provider_id:pid,listing_id:lid,message:message.trim()})});
 toast('Private enquiry sent to '+provider.name+'.');go('/messages/'+thread.id);break;
 }
case 'delete-provider':if(!await lapengConfirm('Delete this provider profile, its listings and photographs? This cannot be undone.',{title:'Delete business profile?',destructive:true}))break;await api('/providers/'+id,{method:'DELETE'});await refresh();go('/dashboard');toast('Profile deleted.');break;case 'accept':await api('/proposals/'+id+'/accept',{method:'POST'});await render();toast('Proposal accepted.');break;case 'assemble':{b.disabled=true;b.textContent='Analyzing…';const x=await api('/ai/assemble/'+id,{method:'POST'});const target=$('#intelligence');target.innerHTML=`<div class="notice ${x.missing_units?'':'good'}">${x.covered_units}/${x.requested_units} units covered · Estimated $${x.estimated_total_usd} USD · ${x.fits_budget?'within budget':'exceeds budget'}</div>${x.plan.map(p=>`<div class="list-item"><div><b>${e(p.name)}</b><p class="meta">${p.units} unit(s) · $${p.subtotal_usd} illustrative cost</p></div></div>`).join('')}<p class="subtle">${e(x.assistant.text)}</p><p class="hint">Analysis: ${e(x.assistant.mode)}. Nobody has accepted or been paid.</p>`;b.disabled=false;b.textContent='Recalculate';break}case 'guardian':{const x=await api('/ai/guardian/'+id,{method:'POST'});$('#guardian').innerHTML=`<div class="notice">${e(x.assessment)}</div><p class="subtle">${e(x.assistant.text)}</p>`;break}case 'paypal':{const p=await api('/paypal/create/'+id,{method:'POST'});if(!p.approve_url)throw Error('PayPal did not return an approval URL');window.location.assign(p.approve_url);break}case 'review':{const score=await lapengPrompt('Rating from 1 to 5');if(!score)return;const text=await lapengPrompt('Describe your completed transaction (minimum eight characters)');if(!text)return;await api('/reviews',{method:'POST',body:JSON.stringify({payment_id:id,score:+score,text})});toast('Verified payment review created.');break}case 'guardian-decide':{const note=await lapengPrompt('Record the evidence-based reason for this decision (visible to case participants):');if(!note)break;await api('/guardian/cases/'+id+'/decision',{method:'POST',body:JSON.stringify({status:b.dataset.status,note})});toast('Decision recorded.');await render();break;}case 'guardian-appeal-decision':{const note=await lapengPrompt('Record an explanation for the appeal outcome:');if(!note)break;await api('/guardian/appeals/'+id+'/decision',{method:'POST',body:JSON.stringify({status:b.dataset.status,note})});toast('Appeal decision recorded.');await render();break;}case 'guardian-appeal':{const reason=await lapengPrompt('Why do you disagree with this decision? Provide context for a human reviewer.');if(!reason)break;await api('/guardian/cases/'+id+'/appeals',{method:'POST',body:JSON.stringify({reason})});toast('Appeal submitted.');await render();break;}case 'report':go('/trust');break}
}catch(err){toast(err.message)}}
async function onReturn(){const params=new URLSearchParams(location.search);const shopid=params.get('shop_return'),shopCancel=params.get('shop_cancel');if(shopid){history.replaceState(null,'','/');if(!state.token){toast('Sign in to verify your PayPal Sandbox checkout');go('/signin');return;}try{const x=await api('/commerce/orders/'+encodeURIComponent(shopid)+'/capture',{method:'POST'});toast(x.verified?'PayPal Sandbox checkout verified.':x.status)}catch(err){toast('Checkout not verified: '+err.message)}await refresh();go('/order/'+shopid);return;}if(shopCancel){history.replaceState(null,'','/');toast('PayPal checkout cancelled. No payment marked paid.');go('/cart');return;}const payid=params.get('paypal_return');const cancel=params.get('paypal_cancel');if(payid){history.replaceState(null,'','/');if(!state.token){toast('Sign in with the buyer account to verify the returned PayPal order.');go('/signin');return}try{const x=await api('/paypal/capture/'+payid,{method:'POST'});toast(x.verified?'PayPal Sandbox payment captured and verified.':'Payment returned, but not verified completed: '+x.status)}catch(err){toast('Capture could not be verified: '+err.message)}await refresh();go('/dashboard')}else if(cancel){history.replaceState(null,'','/');toast('PayPal checkout cancelled. No payment marked completed.')}}

// Floating LAPENG assistant: same compact widget on landing, Explore and workspaces.
let lapengAssistantOpen=false, lapengAssistantBusy=false;
function assistantWidget(){
  if(document.querySelector('#lapeng-assistant-root'))return;
  const node=document.createElement('div');node.id='lapeng-assistant-root';
  node.innerHTML=`<button id="lapeng-ai-toggle" class="lapeng-ai-toggle" aria-label="Open LAPENG assistant" aria-expanded="false" type="button"><span aria-hidden="true">✦</span><span>Ask LAPENG</span></button>
  <section id="lapeng-ai-panel" class="lapeng-ai-panel" role="dialog" aria-label="LAPENG assistant" hidden>
    <div class="lapeng-ai-head"><div><strong>✦ LAPENG Assistant</strong><small>Here to help you explore</small></div><button id="lapeng-ai-close" type="button" aria-label="Close assistant">×</button></div>
    <div id="lapeng-ai-messages" class="lapeng-ai-messages" role="log" aria-live="polite"><div class="lapeng-ai-bubble bot">Hi! I can help you find a product or service, understand listings, or get started as a provider. What are you looking for?</div></div>
    <div class="lapeng-ai-suggestions"><button type="button" data-lapeng-ai-prompt="How can I sell on LAPENG?">Start selling</button><button type="button" data-lapeng-ai-prompt="How do I find clothes or products?">Find products</button><button type="button" data-lapeng-ai-prompt="What payment currencies are supported?">Payments</button><a class="op-ai-link" href="#/opportunities">Plan a complete need ✦</a></div>
    <form id="lapeng-ai-form" class="lapeng-ai-form"><label class="sr-only" for="lapeng-ai-question">Ask LAPENG</label><input id="lapeng-ai-question" maxlength="500" minlength="2" placeholder="Ask about products or services…" required autocomplete="off"><button type="submit" aria-label="Send message">➤</button></form>
    <p class="lapeng-ai-disclaimer">AI responses can be mistaken. No purchase or account action is performed by chat. Do not share sensitive data.</p>
  </section>`;
  document.body.appendChild(node);
  function toggle(open){lapengAssistantOpen=open;document.querySelector('#lapeng-ai-panel').hidden=!open;document.querySelector('#lapeng-ai-toggle').setAttribute('aria-expanded',String(open));if(open)document.querySelector('#lapeng-ai-question').focus();}
  document.querySelector('#lapeng-ai-toggle').addEventListener('click',()=>toggle(!lapengAssistantOpen));
  document.querySelector('#lapeng-ai-close').addEventListener('click',()=>toggle(false));
  document.querySelectorAll('[data-lapeng-ai-prompt]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('#lapeng-ai-question').value=btn.dataset.lapengAiPrompt;document.querySelector('#lapeng-ai-form').requestSubmit();}));
  document.querySelector('#lapeng-ai-form').addEventListener('submit',async ev=>{
    ev.preventDefault();if(lapengAssistantBusy)return;
    const input=document.querySelector('#lapeng-ai-question'),question=input.value.trim();if(question.length<2)return;input.value='';
    const log=document.querySelector('#lapeng-ai-messages');
    const bubble=(text,kind)=>{const elem=document.createElement('div');elem.className='lapeng-ai-bubble '+kind;elem.textContent=text;log.appendChild(elem);log.scrollTop=log.scrollHeight;return elem;};
    bubble(question,'user');const waiting=bubble('Looking into that…','bot');
    lapengAssistantBusy=true;input.disabled=true;
    try{const result=await api('/ai/chat',{method:'POST',body:JSON.stringify({question})});waiting.textContent=result.answer;
      if(/need|organis|organize|event|plan|birthday|multiple services/i.test(question)){const link=document.createElement('a');link.href='#/opportunities';link.className='op-ai-link';link.textContent='Create a plan with real providers →';link.addEventListener('click',()=>{state.opportunityDraft=question;toggle(false);});log.appendChild(link);}if(result.suggestions?.length){const refs=document.createElement('div');refs.className='lapeng-ai-results';
        result.suggestions.forEach(item=>{const a=document.createElement('a');a.href=item.url;a.textContent=item.title+' · '+item.reference;a.addEventListener('click',()=>toggle(false));refs.appendChild(a);});log.appendChild(refs);}
    }catch(ex){waiting.textContent='I could not connect right now. You can still browse Explore, or try again.';}
    finally{lapengAssistantBusy=false;input.disabled=false;log.scrollTop=log.scrollHeight;input.focus();}
  });
}

document.addEventListener('submit',submit);document.addEventListener('click',act);document.addEventListener('change',ev=>{
 const form=ev.target.closest('form[data-form="provider"]');if(!form)return;
 if(ev.target.name==='booking_enabled'){
  const block=form.querySelector('.booking-question-fields');if(block)block.hidden=!ev.target.checked;
 }
 if(ev.target.name==='contact_method'){
  const block=form.querySelector('.business-phone-fields');if(block)block.hidden=ev.target.value==='in_app';
 }
});document.addEventListener('change',ev=>{if(ev.target.id==='workspace'||ev.target.id==='workspace-setting'){switchWorkspace(ev.target.value)}if(ev.target.id==='reduce-motion'){document.documentElement.style.scrollBehavior=ev.target.checked?'auto':'smooth'}});window.addEventListener('hashchange',()=>{recordRoute();render();});
(async()=>{await refresh();await render();assistantWidget();await onReturn()})();

document.addEventListener('change',ev=>{if(ev.target?.id==='slot-options'&&ev.target.value){const [start,end]=ev.target.value.split(':').map(Number);const form=document.querySelector('form[data-form="booking"]');if(form){const local=ts=>{let d=new Date(ts*1000);let offset=d.getTimezoneOffset()*60000;return new Date(d.getTime()-offset).toISOString().slice(0,16)};form.querySelector('[name="start"]').value=local(start);form.querySelector('[name="end"]').value=local(end);}}});

// Mobile navigation: accessible dismissal without modifying routing or auth.
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const top=document.querySelector('.top.mobile-nav-open');if(top){top.classList.remove('mobile-nav-open');const btn=top.querySelector('.mobile-menu-button');if(btn){btn.setAttribute('aria-expanded','false');btn.focus();}}}});
document.addEventListener('click',event=>{const top=document.querySelector('.top.mobile-nav-open');if(top&&!top.contains(event.target)){top.classList.remove('mobile-nav-open');top.querySelector('.mobile-menu-button')?.setAttribute('aria-expanded','false');}});

// Shopping-bag edits are persisted using the existing protected cart PATCH endpoint.
document.addEventListener('change',async event=>{
 const item=event.target.closest('.lapeng-bag-product');
 if(!item || !event.target.matches('[data-cart-variant], [data-cart-quantity]'))return;
 const id=Number(event.target.dataset.cartVariant || event.target.dataset.cartQuantity);
 const option=item.querySelector('[data-cart-variant]')?.value||'';
 const amount=item.querySelector('[data-cart-quantity]');
 const qty=Number(amount?.value);
 if(!Number.isSafeInteger(id)||id<1||!Number.isInteger(qty)||qty<1||qty>Number(amount.max||100)){toast('Select a valid quantity.');await render();return;}
 try{item.classList.add('lapeng-bag-saving');await api('/commerce/cart/'+id,{method:'PATCH',body:JSON.stringify({choice:option,quantity:qty})});await updateCartCount();await render();toast('Bag updated.')}catch(error){toast(error.message||'Could not update item');await render();}
});
